```java
import java.util.*;

public class Main {
    static final long MOD1 = 1000000007L;
    static final long MOD2 = 1000000009L;
    static final long BASE = 911382323L;

    static int n, LOG = 18, timer = 0;
    static String str;
    static ArrayList<Integer>[] g;
    static int[][] fa;
    static int[] dep, size, son, dfn, rev, ans;
    static long[] h1, h2, pow1, pow2;

    // 哈希键
    static class Key {
        int depth;
        long a, b;

        Key(int depth, long a, long b) {
            this.depth = depth;
            this.a = a;
            this.b = b;
        }

        public boolean equals(Object o) {
            if (!(o instanceof Key)) return false;
            Key k = (Key) o;
            return depth == k.depth && a == k.a && b == k.b;
        }

        public int hashCode() {
            long res = depth;
            res = res * 1000003 + a;
            res = res * 1000003 + b;
            return (int)(res ^ (res >>> 32));
        }
    }

    // 建树，求父亲、深度、哈希
    static void build() {
        int[] q = new int[n];
        int head = 0, tail = 0;
        q[tail++] = 1;

        while (head < tail) {
            int u = q[head++];
            for (int v : g[u]) {
                if (v == fa[0][u]) continue;
                fa[0][v] = u;
                dep[v] = dep[u] + 1;

                int c = str.charAt(v - 1) - 'a' + 1;
                h1[v] = (h1[u] * BASE + c) % MOD1;
                h2[v] = (h2[u] * BASE + c) % MOD2;

                q[tail++] = v;
            }
        }

        // 倍增父亲
        for (int k = 1; k < LOG; k++) {
            for (int i = 1; i <= n; i++) {
                fa[k][i] = fa[k - 1][fa[k - 1][i]];
            }
        }

        // 求子树大小和重儿子
        for (int i = n - 1; i >= 0; i--) {
            int u = q[i];
            size[u] = 1;
            for (int v : g[u]) {
                if (v == fa[0][u]) continue;
                size[u] += size[v];
                if (son[u] == 0 || size[v] > size[son[u]]) {
                    son[u] = v;
                }
            }
        }
    }

    // 求 DFS 序
    static void dfsDfn(int u) {
        dfn[u] = ++timer;
        rev[timer] = u;

        for (int v : g[u]) {
            if (v != fa[0][u]) {
                dfsDfn(v);
            }
        }
    }

    // 求 ancestor 的下一层到 x 的字符串哈希
    static Key getKey(int ancestor, int x) {
        int len = dep[x] - dep[ancestor];

        long a = (h1[x] - h1[ancestor] * pow1[len]) % MOD1;
        if (a < 0) a += MOD1;

        long b = (h2[x] - h2[ancestor] * pow2[len]) % MOD2;
        if (b < 0) b += MOD2;

        return new Key(len, a, b);
    }

    // 处理每个节点
    static void dfs(int u) {
        for (int v : g[u]) {
            if (v != fa[0][u]) {
                dfs(v);
            }
        }

        HashMap<Key, Integer> map = new HashMap<>();

        // 先加入重儿子子树
        if (son[u] != 0) {
            int v = son[u];
            for (int i = dfn[v]; i < dfn[v] + size[v]; i++) {
                int x = rev[i];
                Key key = getKey(u, x);
                map.put(key, v);
            }
        }

        // 再处理轻儿子子树
        for (int v : g[u]) {
            if (v == fa[0][u] || v == son[u]) continue;

            // 先查询是否能与之前儿子子树匹配
            for (int i = dfn[v]; i < dfn[v] + size[v]; i++) {
                int x = rev[i];
                Key key = getKey(u, x);

                if (map.containsKey(key) && map.get(key) != v) {
                    int d = dep[x] - dep[u];
                    ans[u] = Math.max(ans[u], 2 * d + 1);
                }
            }

            // 再加入当前儿子子树
            for (int i = dfn[v]; i < dfn[v] + size[v]; i++) {
                int x = rev[i];
                Key key = getKey(u, x);
                map.put(key, v);
            }
        }
    }

    static int[] solve() {
        pow1 = new long[n + 2];
        pow2 = new long[n + 2];
        pow1[0] = pow2[0] = 1;

        for (int i = 1; i <= n + 1; i++) {
            pow1[i] = pow1[i - 1] * BASE % MOD1;
            pow2[i] = pow2[i - 1] * BASE % MOD2;
        }

        build();
        dfsDfn(1);

        Arrays.fill(ans, 1);
        dfs(1);

        return ans;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        n = sc.nextInt();
        str = sc.next();

        g = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            g[i] = new ArrayList<>();
        }

        for (int i = 1; i < n; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            g[u].add(v);
            g[v].add(u);
        }

        fa = new int[LOG][n + 1];
        dep = new int[n + 1];
        size = new int[n + 1];
        son = new int[n + 1];
        dfn = new int[n + 1];
        rev = new int[n + 1];
        ans = new int[n + 1];
        h1 = new long[n + 1];
        h2 = new long[n + 1];

        int[] res = solve();

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            if (i > 1) sb.append(' ');
            sb.append(res[i]);
        }
        System.out.println(sb);
    }
}
