        g[u].push_back(v);
        g[v].push_back(u);
    }

    fa.assign(LOG, vector<int>(n + 1, 0));
    dep.assign(n + 1, 0);
    sz.assign(n + 1, 0);
    son.assign(n + 1, 0);
    dfn.assign(n + 1, 0);
    rev.assign(n + 1, 0);
    h1.assign(n + 1, 0);
    h2.assign(n + 1, 0);

    vector<int> res = solve();

    for (int i = 1; i <= n; i++) {
        if (i > 1) cout << ' ';
        cout << res[i];
    }
    cout << '\n';

